const crypto = require('crypto');

const item = $input.item.json;
const headers = item.headers || {};
const body = item.body || item;
const secret = $env.N8N_WEBHOOK_SECRET || '';

const signature = headers['x-aurelle-signature'] || headers['X-Aurelle-Signature'];
const timestamp = headers['x-aurelle-timestamp'] || headers['X-Aurelle-Timestamp'];
const eventId = headers['x-aurelle-event-id'] || headers['X-Aurelle-Event-ID'];

if (!signature || !timestamp || !eventId) {
  return [{ json: { isValid: false, reason: 'Missing cryptographic signature headers' } }];
}

// 5-minute replay drift check
const occurredMs = new Date(timestamp).getTime();
if (isNaN(occurredMs) || Math.abs(Date.now() - occurredMs) > 300000) {
  return [{ json: { isValid: false, reason: 'Timestamp drift outside 300s window' } }];
}

// HMAC validation
let signatureValid = false;
if (secret) {
  const payloadBytes = Buffer.from(JSON.stringify(body));
  const expectedHmac = crypto.createHmac('sha256', secret).update(payloadBytes).digest('hex');
  signatureValid = (signature.toLowerCase() === expectedHmac.toLowerCase());
} else {
  signatureValid = Boolean($env.NODE_ENV !== 'production');
}

const payload = body.payload || {};

// CRITICAL ANTI-LOOP DEFENSE: Never process failure alerts triggered by failure alerts
if (payload.failed_event_type === 'automation.delivery_failed' || body.event_type !== 'automation.delivery_failed') {
  return [{
    json: {
      isValid: false,
      reason: 'Anti-loop suppression: Recursive failure alert dropped',
    }
  }];
}

return [{
  json: {
    isValid: signatureValid,
    reason: signatureValid ? 'OK' : 'Invalid HMAC signature',
    event_id: body.event_id || eventId,
    failed_event_id: payload.event_id || eventId,
    failed_event_type: payload.failed_event_type || 'unknown',
    failure_category: payload.failure_category || 'max_retries_exceeded',
    attempt_count: payload.attempt_count || 5,
    error_summary: (payload.error_summary || 'Delivery retry limit reached').substring(0, 300),
    failed_at: payload.failed_at || timestamp,
    monitor_url: payload.monitor_url || 'https://aurelle.dsecops88.online/admin/automations',
    recipient_email: $env.ALERT_RECIPIENT_EMAIL || 'alerts@aurelle.dsecops88.online',
  }
}];

